import sys
sys.path.insert(0, 'src')
from workflow import Session, Telemetry

class Env:
    def __init__(self):
        self.listeners=[]; self.deferred={}; self.events=[]; self.warm=[]; self.show_hook=None
    def bind(self, callback): return callback
    def emit(self, packet):
        for callback in list(self.listeners): callback(packet)
    def call(self, name, *args):
        if name == 'listen':
            callback=args[1]; self.listeners.append(callback); return callback
        if name == 'unlisten':
            subscription=args[1]; self.listeners.remove(subscription); self.events.append(('unlisten',)); return None
        if name == 'start':
            for packet in list(self.warm): self.emit(packet)
            return None
        if name == 'decode':
            packet, completion=args[1], args[2]
            if packet.startswith('defer:'):
                self.deferred[packet]=completion; return {'deferred':True}
            return {'deferred':False, 'frame':packet}
        self.events.append((name,)+args)
        if name == 'showProgress' and self.show_hook: self.show_hook(args[0])

def events(env, name): return [e for e in env.events if e[0] == name]
file={'id':'f','token':'f','feed':True,'size':1}
env=Env(); env.warm=['warm']; session=Session(env)
session.select(file)
assert [e[-1]['frame'] for e in events(env,'showProgress')] == ['warm']
assert [e[-1]['frame'] for e in events(env,'recordProgress')] == ['warm']
env.emit('defer:older'); env.emit('defer:newer')
env.deferred['defer:newer']('newer'); env.deferred['defer:older']('older')
assert [e[-1]['frame'] for e in events(env,'showProgress')] == ['warm','newer']
assert [e[-1]['frame'] for e in events(env,'recordProgress')] == ['warm','newer','older']
env.emit('defer:stale'); session.retry(); env.deferred['defer:stale']('stale')
assert [e[-1]['frame'] for e in events(env,'showProgress')] == ['warm','newer','warm']
assert [e[-1]['frame'] for e in events(env,'recordProgress')][-1] == 'stale'
telemetry=Telemetry(env,file); before=len(events(env,'recordDelta')); env.emit('live')
assert len(events(env,'recordDelta')) == before+1
# A warm callback may navigate before the first select receives its handle.
env2=Env(); env2.warm=['warm']; session2=Session(env2); switched=[False]
def navigate(_):
    if not switched[0]:
        switched[0]=True; session2.select(file)
env2.show_hook=navigate
session2.select(file)
assert session2.snapshot()['attemptId'] == 2
assert len(env2.listeners) == 1
print('workflow progress and reentrancy checks passed')
